using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 public static class ProceduralBodyTests {
  static int checks;static void Check(bool v,string label){checks++;if(!v)throw new Exception(label);}static void Wait(Func<bool> f,string label,int seconds=180){var time=System.Diagnostics.Stopwatch.StartNew();while(!f()&&time.Elapsed.TotalSeconds<seconds){Application.DoEvents();Thread.Sleep(15);}Check(f(),label);}static T Result<T>(Task<T> task){Wait(()=>task.IsCompleted,"asynchronous operation completes",240);return task.GetAwaiter().GetResult();}
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var doc=new RobotDocument{Name="Процедурный корпус · проверка"};var joint=doc.Add(null);joint.Mode=RobotJointMode.Вращение_Z;joint.EndX=180;joint.EndY=joint.EndZ=0;joint.OffsetZ=100;joint.Reduction=12;joint.Payload=.5;joint.MotorTemplate=RobotMotorTemplate.STEPPERONLINE_по_вашему_STEP;joint.ApplyMotorTemplate();joint.BodyGenerator=new ProceduralBodySettings();using(var kernel=new CADKernel()){joint.GeneratedBody=Result(Task.Factory.StartNew(()=>ProceduralBodySpec.Generate(kernel,doc,joint,joint.BodyGenerator)));File.WriteAllText(Path.Combine(folder,"generation-checks.json"),CADDocument.Serializer().Serialize(joint.GeneratedBody.Result.Issues),Encoding.UTF8);Check(joint.GeneratedBody.Result.GeometryValid,"native generated housing passes exact checks: "+string.Join("; ",joint.GeneratedBody.Result.Issues.Where(i=>i.Status=="error").Select(i=>i.Message)));Check(joint.GeneratedBody.Result.Parts.Count>=8,"separate frame, actuator halves, motor plate, support and panels");Check(joint.GeneratedBody.Result.Parts.All(p=>p.Step!=null&&p.Preview!=null&&p.Bounds.Length==6),"self-contained STEP and previews");Check(!joint.GeneratedBody.Result.ReadyForManufacture,"no false manufacturing approval");var before=ProceduralBodySpec.Fingerprint(doc,joint,joint.BodyGenerator);joint.Position=10;Check(before==ProceduralBodySpec.Fingerprint(doc,joint,joint.BodyGenerator),"pose does not invalidate native geometry");joint.Position=0;string file=Path.Combine(folder,"Procedural_reference.robot.json");doc.Save(file);var restored=RobotDocument.Parse(File.ReadAllText(file));Check(restored.Joints[0].GeneratedBody.Result.Parts[0].Step==joint.GeneratedBody.Result.Parts[0].Step,"native geometry survives robot project roundtrip");var model=RobotCad.Build(restored);Check(model.Model.Valid,"generated CAD integrates into robot assembly");Check(model.Entries.Values.Count(e=>e.Id.Contains("_proc_"))==joint.GeneratedBody.Result.Parts.Count,"all generated parts bound to correct skeleton");var part=joint.GeneratedBody.Result.Parts.First(p=>p.Id=="rear_cover");var native=CADDocument.ImportStep(Convert.FromBase64String(part.Step),part.Label);var original=kernel.Run(native);var hole=CADTools.Feature("hole");hole.Target=native.Features[0].Id;var face=original.Bodies[0].Faces.First(f=>f.Kind=="plane"&&f.Normal[2]>.9);hole.Faces.Add(face.Id);hole.Point=new[]{38.0,0,face.Center[2]};hole.Values["Diameter"]="3";hole.Values["Through"]="true";native.Features.Add(hole);var modified=kernel.Run(native);Check(modified.Bodies.Sum(b=>b.Volume)<original.Bodies.Sum(b=>b.Volume)-1,"real cylindrical hole modifies exported procedural STEP");}
   using(var robot=new RobotDesignerForm())using(var shell=new WorkspaceShell(robot)){robot.SetDocument(doc);shell.Show();Wait(()=>robot.Scene.Ready&&robot.WebScene.Ready,"Three.js robot viewport starts",100);Application.DoEvents();Thread.Sleep(300);Application.DoEvents();var raw=Result(robot.WebScene.Inspect());string json=CADDocument.Serializer().Deserialize<string>(raw);var state=CADDocument.Serializer().DeserializeObject(json) as Dictionary<string,object>;Check(Convert.ToInt32(state["parts"])>8&&Convert.ToInt32(state["triangles"])>100,"Three.js renders actual robot geometry");Check(Convert.ToInt32(state["canvasWidth"])>=500,"Three.js has real visible viewport");var preview=robot.WebScene.SavePreview(Path.Combine(folder,"robot-threejs.png"));Wait(()=>preview.IsCompleted,"Three.js screenshot saved");preview.GetAwaiter().GetResult();var live=robot.Document.Joints[0];double mountVolume=live.GeneratedBody.Result.Parts.First(p=>p.Id=="actuator_left").Volume;live.EndX=240;robot.SetDocument(robot.Document);Wait(()=>!robot.ProceduralBusy&&live.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(robot.Document,live,live.BodyGenerator),"180 to 240 mm automatically regenerates native housing",240);Check(live.GeneratedBody.Result.GeometryValid&&Math.Abs(live.GeneratedBody.Result.Parts.First(p=>p.Id=="actuator_left").Volume-mountVolume)<.001,"automatic regeneration preserves independent motor mount");robot.SetStage(2);robot.OpenProceduralBody();var generator=shell.Pages.SelectedTab.Tag as ProceduralBodyForm;Check(generator!=null&&!generator.TopLevel,"procedural generator embedded in same application window");Check(Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"generator creates no separate top-level window");shell.ApproveTestClose();shell.Close();}
   File.WriteAllText(Path.Combine(folder,"procedural-results.txt"),"PASS "+checks+" procedural integration assertions: native OCCT housing, STEP drilling, persistence, real Three.js viewport and one-window workspace.\r\n",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"procedural-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
